import{_ as s,C as a,o as n,c as i,j as o,a as t,E as l,a2 as d}from"./chunks/framework.BSaF8iZ6.js";const P=JSON.parse('{"title":"Manage Profile","description":"","frontmatter":{},"headers":[],"relativePath":"seller-panel/manage-profile.md","filePath":"seller-panel/manage-profile.md","lastUpdated":1789411447000}'),p={name:"seller-panel/manage-profile.md"};function g(h,e,u,c,m,f){const r=a("ImagePopup");return n(),i("div",null,[e[0]||(e[0]=o("h1",{id:"manage-profile",tabindex:"-1"},[t("Manage Profile "),o("a",{class:"header-anchor",href:"#manage-profile","aria-label":'Permalink to "Manage Profile"'},"​")],-1)),e[1]||(e[1]=o("div",{class:"page-roles"},[o("span",{class:"role role--seller"},"Seller")],-1)),e[2]||(e[2]=o("p",null,"Your profile holds your shop's details: the name and logo customers see, your description and policies, your address and your contact details. Customers see much of it on your shop page.",-1)),e[3]||(e[3]=o("p",null,[t("Only the shop owner can open this page. To open it, click your profile icon at the top right of the Seller Panel, then click "),o("strong",null,"My Profile"),t(".")],-1)),l(r,{src:"/images/seller-panel/manage-profile.png",alt:"The Manage Profile page"}),e[4]||(e[4]=d('<h2 id="complete-your-profile" tabindex="-1">Complete your profile <a class="header-anchor" href="#complete-your-profile" aria-label="Permalink to &quot;Complete your profile&quot;">​</a></h2><p>You can&#39;t list products until the required details are filled in.</p><ol><li>Open <strong>My Profile</strong>.</li><li>Upload your banner and logo. Use the menu on each image and choose <strong>Upload New Banner</strong> or <strong>Upload New Logo</strong>. A banner in a 3:1 ratio, around 1320×300 pixels, and a square logo fit best. Each image must be within the store&#39;s upload limit, 10 MB unless the store changes it.</li><li>In <strong>General</strong>, check your <strong>Name</strong>, <strong>Email</strong>, <strong>Slug</strong> and <strong>Business Name</strong>, and enter your <strong>Phone</strong>.</li><li>In <strong>Description</strong>, write your <strong>Business Description</strong>.</li><li>In <strong>Address</strong>, enter your <strong>Address</strong>, <strong>City</strong>, <strong>Country</strong>, <strong>State</strong> and <strong>Postcode</strong>.</li><li>Fill in the optional cards, such as <strong>Policies</strong> and <strong>Social Links</strong>.</li><li>Click <strong>Save Profile</strong>.</li></ol><p>You&#39;ll see <strong>Your Profile is updated successfully</strong> and receive a confirmation email.</p><p>If your store has more than one channel or language, choose it at the top of the page before you edit the fields marked with a channel or language name.</p><h2 id="the-profile-cards" tabindex="-1">The profile cards <a class="header-anchor" href="#the-profile-cards" aria-label="Permalink to &quot;The profile cards&quot;">​</a></h2><p>The store decides which cards and fields appear. By default they are:</p><table tabindex="0"><thead><tr><th>Card</th><th>Fields</th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Name, Email, Phone, Slug, Business Name</td></tr><tr><td><strong>Description</strong></td><td>Business Description</td></tr><tr><td><strong>Policies</strong></td><td>Return Policy, Shipping Policy, Privacy Policy</td></tr><tr><td><strong>Meta Description</strong></td><td>Meta Title, Meta Keywords, Meta Description, with a preview of how your shop appears in search results</td></tr><tr><td><strong>Address</strong></td><td>Address, City, Country, State, Postcode</td></tr><tr><td><strong>Social Links</strong></td><td>Facebook, Instagram, YouTube</td></tr><tr><td><strong>Settings</strong></td><td>Minimum Order Amount, Google Analytics ID</td></tr></tbody></table><p>Changing your <strong>Slug</strong> changes the address of your shop page, so links you have shared before stop working.</p><p><strong>Minimum Order Amount</strong> is the least a customer must spend with you in one order. It appears when the store allows it.</p><h2 id="shop-information" tabindex="-1">Shop Information <a class="header-anchor" href="#shop-information" aria-label="Permalink to &quot;Shop Information&quot;">​</a></h2><p>The <strong>Shop Information</strong> card shows what the store has set for you. When the store uses subscription plans, it appears only while you have an active plan. You can&#39;t change it here:</p><ul><li><strong>Admin Commission</strong> — the commission the store takes from your invoiced sales.</li><li><strong>Magic AI</strong> — whether Generative AI is on for your shop, your limit, and how many generations you have used. It appears when the store uses Generative AI. See <a href="./../generative-ai/usage-limits">Usage Limits</a>.</li><li><strong>Restricted Categories</strong> — categories you can&#39;t use.</li><li><strong>Allowed Product Type</strong> — the product types you can sell.</li><li><strong>Payment Methods</strong> and <strong>Shipping Methods</strong> — what the store offers customers at checkout.</li></ul><h2 id="where-customers-see-your-profile" tabindex="-1">Where customers see your profile <a class="header-anchor" href="#where-customers-see-your-profile" aria-label="Permalink to &quot;Where customers see your profile&quot;">​</a></h2><p>Your banner, logo, business name and address appear at the top of your shop page. Your description and the policies you filled in appear in its <strong>About</strong> tab. See <a href="./../storefront/seller-shop-page">Seller Shop Page</a>.</p>',15))])}const b=s(p,[["render",g]]);export{P as __pageData,b as default};
